function badge(string $status,string $date=''): string {
    $labels=['published'=>'Yayında','draft'=>'Taslak','archived'=>'Arşiv','new'=>'Yeni','read'=>'Okundu','replied'=>'Yanıtlandı'];
    if($status==='published'&&$date && strtotime($date)>time())return '<span class="badge scheduled">Planlandı</span>';
    return '<span class="badge '.e($status).'">'.e($labels[$status]??$status).'</span>';
}
